list(methodId?: string): AlgorithmTaskView[] {
  const rows = methodId === undefined
    ? this.db.prepare('SELECT task_id FROM algorithm_calls ORDER BY created_at DESC,task_id LIMIT 20').all()
    : this.db.prepare('SELECT task_id FROM algorithm_calls WHERE method_id=? ORDER BY created_at DESC,task_id LIMIT 20').all(methodId);
  return rows.map(row => this.view(String(row.task_id)));

test('new task contract never recommends bulk processing; module actions derive from existing ports', async () => {
  const { processingSessionContract, PRODUCTION_MODULES, stepModuleForAction } = await import('../collection/production-module-ports.js');
  const processing = processingSessionContract();
  const files = bdSessionToolContract(catalog).toolGroups.find(item => item.id === 'files')!;
  assert.equal(processing.execute, 'data.processing.execute');
  assert.deepEqual(processing.moduleActions,
    PRODUCTION_MODULES.filter(module => stepModuleForAction(module.action) !== null).map(module => module.action));
  assert.ok(files.tools.includes(processing.execute));
  assert.ok(files.tools.includes(processing.recover), 'existing single-step plans retain explicit artifact recovery');
  assert.equal(files.tools.includes('data.processing.run'), false);
  assert.deepEqual(files.legacyRecovery, processing.legacyRecovery);
  assert.equal(files.legacyRecovery?.newTasks, false);
});

test('BD capability response and session tool groups agree about stepwise work and historical recovery', async () => {
  const { CoreDatabase } = await import('../../platform/state/database.js');
  const { ConversationAlgorithmBridge } = await import('./conversation-algorithms.js');
  const { processingSessionContract } = await import('../collection/production-module-ports.js');
  const database = new CoreDatabase(':memory:');
  let dispatchChecks = 0;
  try {
    const bridge = new ConversationAlgorithmBridge({
      database, core: {} as never, origin: () => ({ conversationId: 'isolated', branchId: 'main' } as never),
      companion: { bd: { assertDispatch: () => { dispatchChecks++; } },
        processing: { catalog: () => ({ cleaningEngine: { status: 'ready' } }),
          moduleCapability: () => ({ status: 'ready', engine: 'fixed' }) } } as never,
    });
    const result = await bridge.execute({ task: { id: 'capability-only', action: 'bd.session.capabilities', args: {} },
      signal: new AbortController().signal, assertAuthorized: () => ({ approvalId: null }) } as never);
    const preview = (result.data as any).modelPreview;
    assert.equal(preview.onDemand.cleaning.execute, processingSessionContract().execute);
    assert.equal(preview.onDemand.cleaning.recover, 'data.processing.recover');
    assert.deepEqual(preview.onDemand.cleaning.moduleActions, processingSessionContract().moduleActions);
    assert.equal(preview.onDemand.cleaning.legacyRecovery.newTasks, false);
    assert.equal(dispatchChecks, 1);
    assert.equal(preview.parallelModuleDirectory.autoTrigger, false);
  } finally { database.close(); }
});

/** 按执行器投影同一目录，供旧请求适配和工具选项复用；不再另写支持动作名单。 */
export function sourceOperationsForAction(action: SourceOperationView['run']['action']): SourceOperationView[] {
  const operations = [...Object.values(providerOperations).flat(),
    ...publicKlineProviders.flatMap(provider => sourceOperations(provider.id))];
  return [...new Map(operations.filter(operation => operation.run.action === action)
    .map(operation => [operation.id, operation])).values()];
}

test('主源与历史备用资格共用校验，停用、显式空备用、市场范围规则保持一致', () => {
  const { root, settings } = isolatedSettings();
  const outcome = (check: () => SourceConnection) => {
    try { return { id: check().id }; } catch (error) { return { code: sourceCode(error) }; }
  };
  try {
    for (const [connection, scope] of [['tdx-primary', 'CN/A_STOCK'], ['ths-scope-backup', 'CN/A_STOCK'],
      ['eastmoney-disabled', 'CN/A_STOCK'], ['tdx-primary', 'US/STOCK'], ['tdx-primary', 'MISSING']] as const) {
      assert.deepEqual(outcome(() => settings.assertOperationFallbackEnabled(connection, scope, 'minute_bars')),
        outcome(() => settings.assertOperationConnectionEnabled(connection, scope, 'minute_bars')));
    }
    const current = settings.get();
    settings.update({ ...current, plugins: current.plugins.map(plugin => plugin.id === 'tdx' ? { ...plugin, enabled: false } : plugin) });
    assert.equal(outcome(() => settings.assertOperationFallbackEnabled('tdx-primary', 'CN/A_STOCK', 'minute_bars')).code, 'SOURCE_DISABLED');
  } finally { rmSync(root, { recursive: true, force: true }); }
});

import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

/** 已清理模块的未使用声明门禁；其他模块的历史告警明确报告，不静默宣称全仓清零。 */
export const CLEANED_LOGIC_FILES = new Set([
  'apps/server/algorithm-routes.ts', 'apps/server/workspace-routes.ts', 'apps/server/source-settings-routes.ts',
  'apps/server/logic-cleanup.test.ts',
  'apps/web/src/App.tsx', 'apps/web/src/algorithm-api.ts',
  'apps/web/src/ui/ToolsPage.tsx', 'apps/web/src/ui/SettingsPage.tsx', 'apps/web/src/ui/ComputationPanel.tsx',
  'apps/web/src/ui/useAlgorithmResult.ts', 'apps/web/src/ui/useStoredSelection.ts', 'apps/web/src/ui/logic-cleanup.test.tsx',
  'modules/financial/algorithm-service.ts', 'modules/financial/conversation-algorithms.ts',
  'modules/financial/basic-algorithm-tool-contract.ts', 'modules/financial/basic-algorithm-tool-contract.test.ts',
  'plugins/api-sources/operations.ts',
]);
const unusedCodes = new Set(['6133', '6138', '6192', '6196', '6198', '6199']);
export function classifyDiagnostics(output, checked = CLEANED_LOGIC_FILES) {
  const failures = [], deferred = [];
  for (const line of output.split(/\r?\n/u).filter(line => line.trim())) {
    const match = /^(.*?)\(\d+,\d+\): error TS(\d+): /u.exec(line);
    const file = match?.[1].replaceAll('\\', '/').replace(/^\.\//u, '');
    // 非未使用声明错误、未知输出和本轮清理模块的告警都必须失败。
    if (!match || !unusedCodes.has(match[2]) || checked.has(file)) failures.push(line);
    else deferred.push(line);
  }
  return { failures, deferred };
}
export function runMaintenanceCheck() {
  const root = fileURLToPath(new URL('..', import.meta.url));
  const result = spawnSync(process.execPath, ['node_modules/typescript/bin/tsc', '--noEmit', '--pretty', 'false',
    '--noUnusedLocals', '--noUnusedParameters'], { cwd: root, encoding: 'utf8', timeout: 120_000, maxBuffer: 8 * 1024 * 1024 });
  if (result.error || result.signal) throw new Error(`LOGIC_CHECK_TOOL_FAILED: 未完成类型检查：${result.error?.message ?? result.signal}`);
  const { failures, deferred } = classifyDiagnostics(`${result.stdout ?? ''}\n${result.stderr ?? ''}`);
  if (failures.length || result.status !== 0 && !deferred.length) {
    throw new Error(`LOGIC_CHECK_FAILED: 清理范围内存在未使用声明，或类型检查失败。\n${failures.join('\n')}`);
  }
  console.log(`LOGIC_MAINTENANCE_OK: ${CLEANED_LOGIC_FILES.size} 个已清理文件没有未使用声明。`);
  console.log(`DEFERRED_UNUSED_DIAGNOSTICS: 其他模块仍有 ${deferred.length} 条历史告警；未作为本轮已清理内容。`);
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try { runMaintenanceCheck(); }
  catch (error) { console.error(error.message); process.exitCode = 1; }
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { classifyDiagnostics } from './logic-maintenance-check.mjs';

test('本轮范围告警失败，历史范围仅允许明确的未使用声明代码', () => {
  const checked = new Set(['apps/web/src/App.tsx']);
  const result = classifyDiagnostics([
    "apps\\web\\src\\App.tsx(2,3): error TS6133: 'obsolete' is declared but never read.",
    "modules/old.ts(9,1): error TS6196: 'OldShape' is declared but never used.",
    "modules/old.ts(10,1): error TS2322: Type 'number' is not assignable to type 'string'.",
    'unexpected compiler error',
  ].join('\n'), checked);
  assert.equal(result.failures.length, 3);
  assert.equal(result.deferred.length, 1);
  assert.match(result.deferred[0], /OldShape/u);
});

test('空输出没有历史告警，不借空输出伪造错误分类', () => {
  assert.deepEqual(classifyDiagnostics('\n\r\n'), { failures: [], deferred: [] });
});
